package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.ApiResponse; import in.kabadiwala.connect.service.NotificationService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/api/v1/notifications") public class NotificationController {private final NotificationService s;public NotificationController(NotificationService s){this.s=s;} @GetMapping ApiResponse<?> list(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok("Notifications",Map.of("items",s.list(a.getName(),page,size),"unread",s.unread(a.getName())));} @PatchMapping("/{id}/read") ApiResponse<?> read(Authentication a,@PathVariable String id){s.read(a.getName(),id);return ApiResponse.ok("Marked read",null);} @PatchMapping("/read-all") ApiResponse<?> all(Authentication a){s.readAll(a.getName());return ApiResponse.ok("All marked read",null);}}
